import { uniqueStrings } from './unique_changed.mjs';
import assert from 'node:assert';

// Basic dedup preserving order
assert.deepStrictEqual(uniqueStrings(['a','b','a','c','b']), ['a','b','c']);

// Case-insensitive dedup, original spelling preserved
assert.deepStrictEqual(uniqueStrings(['Apple','apple','APPLE','Banana']), ['Apple','Banana']);

// Whitespace not trimmed
assert.deepStrictEqual(uniqueStrings([' x ','x',' x ']), [' x ','x']);

// Empty input
assert.deepStrictEqual(uniqueStrings([]), []);

// Input not mutated
const input = ['A','a','B'];
const snapshot = [...input];
uniqueStrings(input);
assert.deepStrictEqual(input, snapshot);

// Returns a new array (not same reference)
const out = uniqueStrings(['a','b']);
assert.notStrictEqual(out, ['a','b']);

console.log('All checks passed.');
"

